head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70006";
scwin.linkState = "";
scwin.today = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.today = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.today ?? ""))(dma_pageContext.get("today"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.today ?? ""))(dma_pageContext.get("today")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.today ?? ""))(dma_pageContext.get("today"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.today ?? ""))(dma_pageContext.get("today"))));
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70006.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — reviewYn, isExaServiced, today

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "input_20", fn: function(){ return ((dma_pageContext.get("reviewYn") ?? "") !== 'Y'); } }, { id: "input_22", fn: function(){ return ((dma_pageContext.get("reviewYn") ?? "") === 'Y'); } }, { id: "input_23", fn: function(){ return ((dma_pageContext.get("reviewYn") ?? "") === 'Y'); } }, { id: "btn_reviewReq", fn: function(){ return ((dma_pageContext.get("isExaServiced") ?? "") !== 'N' && (dma_pageContext.get("reviewYn") ?? "") !== 'Y'); } }, { id: "if_wrtYn", fn: function(){ return ((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === 'Y'); } }, { id: "if_wrtYn_2", fn: function(){ return ((String(((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })())) == null ? '' : ((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()))).length === 0) || (dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === '' || (dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === 'N'); } }, { id: "btn_setDocumentForm", fn: function(){ return ((dlt_documentVo.getCellData(0, "docNo") ?? (() => { throw new Error("unresolved:" + "entity.docNo"); })()) !== '00000000000000'); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dlt_documentVo.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "entity.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "img_61", fn: function(){ return ((dlt_documentVo.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "entity.formMandtryTpCd"); })()) === '1'); } }, { id: "img_63", fn: function(){ return ((dlt_documentVo.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "entity.formMandtryTpCd"); })()) === '2'); } }, { id: "img_65", fn: function(){ return ((dlt_documentVo.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "entity.formMandtryTpCd"); })()) === '3'); } }, { id: "img_68", fn: function(){ return ((dlt_documentVo.getCellData(0, "disclsDstYn") ?? (() => { throw new Error("unresolved:" + "entity.disclsDstYn"); })()) === 'N'); } }, { id: "img_70", fn: function(){ return ((dlt_documentVo.getCellData(0, "disclsDstYn") ?? (() => { throw new Error("unresolved:" + "entity.disclsDstYn"); })()) === 'Y'); } }, { id: "if_wrtYn_3", fn: function(){ return ((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === 'Y'); } }, { id: "if_wrtYn_4", fn: function(){ return ((String(((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })())) == null ? '' : ((dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()))).length === 0) || (dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === '' || (dlt_documentVo.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "entity.wrtYn"); })()) === 'N'); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dlt_documentVo.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "entity.wrtrptMaindocTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_40", entity: "dlt_documentVo", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return " " + String(v("formKorNm")); } }, { childId: "btn_setDocumentForm", fn: function (v, i) { return String(v("formKorNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("docNo")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("formKorNm")); } }, { childId: "btn_setDocumentForm_2", fn: function (v, i) { return String(v("formKorNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("docNo")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("formKorNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
