///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDocumentSubmit
 * @description fn Document Submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDocumentSubmit = async function (action) {
    const sbmOptions = {
        id: "tx_fnDocumentSubmit",
        method: "post",
        action: action ?? "/submission/disclosure.do?method=searchDisclosureContent&prnInfoIncldSubmitYn=",
        ref: "dma_fnDocumentSubmitReq",
        target: "dlt_documentVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_document_submit_do
 * @description document submit do 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_document_submit_do = async function () {
    const sbmOptions = {
        id: "tx_fn_document_submit_do",
        method: "post",
        action: "/discls/disclosure.do",
        ref: "dma_documentSubmitDoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_openDataPopup
 * @description open Data Popup 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_openDataPopup = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — disclosureCommon.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — disclosureCommon.do", unresolved: "action:disclosureCommon.do" };
};

/**
