/**
 * @method
 * @name openDataPopup
 * @description open Data Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDataPopup = async function () {
    const comObj = (document.comFrm || { elements: [] });
    const disclosureFrm = (document.disclosureFrm || { elements: [] });
    $c.util.getComponent("dma_openDataPopupReq").set("keyValue", scwin.linkState);
    $c.util.getComponent("dma_openDataPopupReq").set("formCd", $c.util.getComponent("dma_openDataPopupReq").get("formCd"));
    $c.util.getComponent("dma_openDataPopupReq").set("formVer", $c.util.getComponent("dma_openDataPopupReq").get("formVer"));
    let winId = "";
    let optVal = "";
    comObj.action = "disclosureCommon.do";
    $c.util.getComponent("dma_openDataPopupReq").set("isurCd", (document.submitFrm || { elements: [] }).tgtIsurCd.value);
    if (scwin.linkState === '1') {
        $c.util.getComponent("dma_openDataPopupReq").set("method", "getBasicData");
        optVal = scwin.getCenterOpt('350', '250');
        winId = "generateData";
    } else {
        $c.util.getComponent("dma_openDataPopupReq").set("method", "getComList");
        optVal = scwin.getCenterOpt('1300', '600');
        winId = "viewComList";
    }
    comObj.target = winId;
    $c.win.openPopup("", { id: winId }, {});
    await scwin.tx_openDataPopup();
};

/**
 * @method
 * @name getCenterOpt
 * @description get Center Opt 처리
 * @param {*} w w
 * @param {*} h h
 * @returns {void}
 * @hidden N
 */
scwin.getCenterOpt = function (w, h) {
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    return "left=" + l + ",top=" + t + ",width=" + w + ",height=" + h + ",scrollbars=no,resizable=yes";
};

