        await $c.win.alert("본문 공시가 [작성]된 상태일때 전송이 가능합니다.");
        return false;
    }
    const applNo = (document.disclosureFrm || { elements: [] }).applNo.value;
    if (await $c.win.confirm("KIND 제출시스템으로 전송하시겠습니까?")) {
